import{_ as l,a0 as s,w as i,s as h,I as o,x as n,a1 as r,A as a,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"AI 內容審核最早的大規模落地，9 年前 Pornhub 就幹了 | LCTT x X-CMD","titleTemplate":false,"description":"2017 年 10 月，Pornhub 上線 CV 模型識別 10000+ 表演者、每天掃描 5 萬段視頻。比 OpenAI CLIP、Meta SEER 都早，是 AI 內容理解最早的大規模工業實踐之一。9 年後重看，這是 RLHF + CV 內容審核範式的雛形。","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"AI 內容審核最早的大規模落地，9 年前 Pornhub 就幹了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2017 年 10 月，Pornhub 上線 CV 模型識別 10000+ 表演者、每天掃描 5 萬段視頻。比 OpenAI CLIP、Meta SEER 都早，是 AI 內容理解最早的大規模工業實踐之一。9 年後重看，這是 RLHF + CV 內容審核範式的雛形。"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171010 Pornhub launches new AI to watch and tag porn so humans dont have to.digest","title":"AI 內容審核最早的大規模落地，9 年前 Pornhub 就幹了","tag":"201710","desc":"2017 年 10 月，Pornhub 上線 CV 模型識別 10000+ 表演者、每天掃描 5 萬段視頻。比 OpenAI CLIP、Meta SEER 都早，是 AI 內容理解最早的大規模工業實踐之一。9 年後重看，這是 RLHF + CV 內容審核範式的雛形。"},"relativePath":"201710/20171010 Pornhub launches new AI to watch and tag porn so humans dont have to.digest.md","filePath":"[post].md"}'),p={name:"201710/20171010 Pornhub launches new AI to watch and tag porn so humans dont have to.digest.md"};function I(d,t,A,b,P,g){const e=s("Link");return i(),h("div",null,[t[13]||(t[13]=o("h1",{id:"ai-內容審核最早的大規模落地-9-年前-pornhub-就幹了",tabindex:"-1"},[n("AI 內容審核最早的大規模落地，9 年前 Pornhub 就幹了 "),o("a",{class:"header-anchor",href:"#ai-內容審核最早的大規模落地-9-年前-pornhub-就幹了","aria-label":"Permalink to “AI 內容審核最早的大規模落地，9 年前 Pornhub 就幹了”"},"​")],-1)),o("blockquote",null,[o("p",null,[t[1]||(t[1]=n("老文新評 #038 · ",-1)),r(e,{href:"https://thenextweb.com/artificial-intelligence/2017/10/11/pornhub-ai-watch-tag/",rel:"nofollow noopener"},{default:a(()=>[...t[0]||(t[0]=[n("thenextweb.com",-1)])]),_:1}),t[2]||(t[2]=n(" · 2017-10-10",-1))])]),t[14]||(t[14]=u('<p>2017 年 10 月，Pornhub 上線了一套 CV 模型，能識別 10000+ 表演者、每天掃描 5 萬段視頻——這是 AI 內容理解最早的大規模工業實踐，比 OpenAI CLIP 還早半年。那時候 ImageNet 時代剛結束，深度學習在人臉識別上接近人類水平，但「工業化地用 CV 跑全量視頻」還沒成熟樣本。Pornhub 是當時少數把模型推到日均 50 萬級別處理量的玩家。</p><h2 id="文章講了啥" tabindex="-1">文章講了啥 <a class="header-anchor" href="#文章講了啥" aria-label="Permalink to “文章講了啥”">​</a></h2><p>Pornhub 副總裁 Corey Price 在 2017 年 10 月宣佈，公司部署了一套計算機視覺模型：訓練樣本是數千段視頻和表演者正片照，輸出是演員名字 + 內容分類（户外 / 金髮等）。模型每天掃描 5 萬段新增視頻，1 年內要編目全站 500 萬視頻。</p><p>運營上有個聰明設計：用户對 AI 給的標籤可以投支持 / 反對票，反饋迴流進模型訓練。Price 把它包裝成&quot;解放每日閲片無數的視頻審核員&quot;的故事——用 AI 替代人工是核心賣點。</p><h2 id="_9-年後重讀" tabindex="-1">9 年後重讀 <a class="header-anchor" href="#_9-年後重讀" aria-label="Permalink to “9 年後重讀”">​</a></h2><p>Pornhub 2017 年這套系統的幾個組件，今天看都屬於&quot;提前用對了模式&quot;。</p><ul><li><strong>大規模 CV 落地</strong>：2017 年 ImageNet 時代剛結束，深度學習在人臉識別上接近人類水平，但&quot;工業化地用 CV 跑全量視頻&quot;還沒成熟樣本。Pornhub 是當時少數把模型推到日均 50 萬級別處理量的玩家。後來 OpenAI 用 CLIP 做多模態理解、Meta 用 SEER 做自監督、Google 用 Gemini 做視頻理解——它們都用的是同一套範式，只不過 Pornhub 9 年前就在跑。</li><li><strong>用户反饋閉環</strong>：讓用户對標籤投支持 / 反對票，2017 年這是&quot;土法上馬&quot;。但這套機制本質就是 RLHF 的早期形態——人類反饋 → 模型迭代。今天所有主流大模型公司都在做同一件事，只不過 Pornhub 當時讓&quot;打飛機的人&quot;貢獻了訓練數據。</li><li><strong>替代人工的承諾</strong>：文章把 AI 上線包裝成&quot;讓閲片審核員終於解放&quot;。9 年後看這話有點諷刺——審核員沒被完全解放，但工作量大幅減少；同時引出新問題：AI 誤判、偏見、漏報、對抗樣本。Pornhub 當年沒預料到這些問題，今天所有內容平台都在處理。</li></ul><p>更要緊的是，2017 年的 Pornhub 沒有&quot;AI Agent&quot;概念——它只是&quot;CV 分類器 + 人工反饋&quot;。但 2026 年回頭看，這正是 AI Agent 範式的雛形：感知（CV 抽取特徵）→ 決策（標籤分類）→ 行動（寫入資料庫）→ 反饋（用户投票再訓練）。這個流水線今天所有 AI Agent 平台都還在用。</p><h2 id="把-ai-當賣點-vs-把-ai-當工具" tabindex="-1">把 AI 當賣點 vs 把 AI 當工具 <a class="header-anchor" href="#把-ai-當賣點-vs-把-ai-當工具" aria-label="Permalink to “把 AI 當賣點 vs 把 AI 當工具”">​</a></h2><p>文章裏有個細節值得拎出來：Pornhub 把 AI 包裝成&quot;用户也參與貢獻&quot;的協作故事——你點支持 / 反對票，就是在幫 AI 變聰明。</p><p>這跟 9 年後某些 AI 公司的&quot;民主化&quot;敍事幾乎一模一樣。區別是：Pornhub 當年的反饋是真的迴流進了模型，2026 年某些大模型公司收集的&quot;用户反饋&quot;大部分進了數據倉庫沒回訓練管道。</p><p>更深一層：&quot;讓用户參與 AI 訓練&quot;是個有真實價值的設計，但也是個有真實代價的設計。Pornhub 當年收集的用户反饋不可避免帶偏見——某些品類的標籤被反覆支持、某些則被反覆反對，模型被慢慢推向一個特定&quot;審美&quot;的分佈。這種&quot;用户投票決定 AI 價值取向&quot;的設計，今天做內容審核的人應該警惕——用户覺得對的，未必是平台合規想要的。</p><p>AI 內容審核最大的難題不是技術，是&quot;訓練分佈和合規要求之間的鴻溝&quot;。Pornhub 9 年前沒遇到這個問題，是因為成人網站當時基本沒有&quot;合規&quot;概念——只有 SEO。今天所有大型內容平台都面對這個問題：用户投反對票的內容，往往是法律要求保留的；用户投支持票的內容，往往是法律要求刪除的。</p><p>這條 9 年前的新聞真正的價值，是它展示了&quot;AI 內容審核&quot;這條賽道的起點有多低——一家成人網站、單功能模型、幾千張訓練圖、幾萬段視頻每天。再過 9 年，這條賽道變成了幾百億美元的產業、幾百萬小時的訓練數據、幾千個模型 SKU。起點從來不是問題，跑完賽程才是問題。</p><hr><p><strong>出處</strong></p>',16)),o("ul",null,[o("li",null,[t[4]||(t[4]=o("strong",null,"原文",-1)),t[5]||(t[5]=n("（ARR 風險）：",-1)),r(e,{href:"https://thenextweb.com/artificial-intelligence/2017/10/11/pornhub-ai-watch-tag/",rel:"nofollow noopener"},{default:a(()=>[...t[3]||(t[3]=[n("thenextweb.com",-1)])]),_:1})]),o("li",null,[t[7]||(t[7]=o("strong",null,"LCTT 譯稿源檔",-1)),t[8]||(t[8]=n("：",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[n("github.com/LCTT/TranslateProject",-1)])]),_:1})]),o("li",null,[t[10]||(t[10]=o("strong",null,"原譯",-1)),t[11]||(t[11]=n("：",-1)),r(e,{href:"https://lctt.x-cmd.com/201710/20171010%20Pornhub%20launches%20new%20AI%20to%20watch%20and%20tag%20porn%20so%20humans%20dont%20have%20to/"},{default:a(()=>[...t[9]||(t[9]=[n("linux.cn",-1)])]),_:1})]),t[12]||(t[12]=o("li",null,[o("strong",null,"發佈"),n("：2017-10-10")],-1))]),t[15]||(t[15]=u('<hr><h2 id="這些觀點今天還成立嗎" tabindex="-1">這些觀點今天還成立嗎？ <a class="header-anchor" href="#這些觀點今天還成立嗎" aria-label="Permalink to “這些觀點今天還成立嗎？”">​</a></h2><ul><li>✅ <strong>CV 識別表演者是工業級能力</strong> —— 現在 CLIP、VLM、Video-LLaVA 都已超越，但 Pornhub 是先驅</li><li>✅ <strong>用户反饋反哺模型</strong> —— RLHF / VLM 主流訓練範式，2017 年 Pornhub 的&quot;投票&quot;模式本質就是早期 RLHF</li><li>⚠️ <strong>AI 解放人工審核員</strong> —— 部分對，但引出新問題（AI 偏見、漏判、對抗樣本）</li><li>⚠️ <strong>每天 5 萬視頻是大數字</strong> —— 現在的 AI 一天能掃 500 萬+；但 Pornhub 當年是這個數量級的先行者</li><li>⚠️ <strong>1 年內索引 500 萬視頻</strong> —— 2026 年的多模態模型 1 天就能完成同等工作，但&quot;工業化跑通&quot;這條 Pornhub 先做到了</li></ul>',3))])}const T=l(p,[["render",I]]);export{C as __pageData,T as default};
